head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15900";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15900.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_spotIsuTrdMktTpCd", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15900.btn_Search_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15900.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_dsclDataList_oncellclick
 * @description grd_dsclDataList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_dsclDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_dsclDataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_dsclDataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { await scwin.fileDown(r["contnId"], r["contnAttachSeq"], r["attachFileNm"], r["wrtDdtm"]); return; } await scwin.searchDetail(r["contnId"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_dsclDataList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_109_onclick
 * @description krxpage_pagenavigator_109 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_109_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_109.page' }); } await scwin.tx_load_list(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/dsclData.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_SearchDetail
 * @description Search Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchDetail",
        method: "post",
        action: "/support/dsclData.do",
        ref: "dma_SearchDetailReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/support/dsclData.do?method=searchDsclData",
        ref: "dma_loadListReq",
        target: "dlt_dsclDataList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_109").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/support/fileDownload.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name grd_dsclDataList_fillAct
 * @description grd dscl Data List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_dsclDataList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_dsclDataList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_dsclDataList.fillAct' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.dsclDataForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchDsclData');
    frm.action = 'dsclData.do';
    const nr = await scwin.tx_fn_Search();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil15901/jldfil15901.xml", { "method": 'searchDsclData' });
    }
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function (contnId) {
    const frm = (document.dsclDataForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchDsclDataDetail');
    $c.util.getComponent('dma_SearchReq').set('contnId', contnId);
    frm.action = 'dsclData.do';
    const nr = await scwin.tx_fn_SearchDetail();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil15901/jldfil15901.xml", { "method": 'searchDsclDataDetail', "contnId": contnId });
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} contnId contnId
 * @param {*} attachSeq attachSeq
 * @param {String} attachFileNm attachFileNm
 * @param {*} wrtDdtm wrtDdtm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (contnId, attachSeq, attachFileNm, wrtDdtm) {
    const frm = (document.fileDownForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchBbsAttachFile');
    $c.util.getComponent('dma_SearchReq').set('contnId', contnId);
    $c.util.getComponent('dma_SearchReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_SearchReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_SearchReq').set('wrtDdtm', wrtDdtm);
    frm.action = '/support/fileDownload.do';
    await scwin.tx_fn_FileDown();
};
